CREATE FUNCTION public.evaluate_farmer_alerts() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE changed integer; BEGIN WITH prices AS (SELECT f.owner_id,f.kind,f.id,r.date,r.modal_price FROM public.farmer_records f JOIN LATERAL (SELECT a.date,a.modal_price FROM public.agri_reports a WHERE a.official AND NOT a.suspicious AND a.price_unit='INR/quintal' AND a.commodity=f.payload->>'crop' AND a.variety=f.payload->>'variety' AND (a.state||'|'||a.district||'|'||a.market)=f.payload->>'marketKey' AND a.date>=((f.payload->>'createdAt')::timestamptz AT TIME ZONE 'Asia/Kolkata')::date ORDER BY a.date DESC,a.retrieved_at DESC LIMIT 1) r ON true WHERE f.kind='alert') UPDATE public.farmer_records f SET payload=jsonb_set(f.payload,'{evaluation}',jsonb_build_object('checkedAt',now(),'reportDate',p.date,'price',p.modal_price,'triggered',CASE WHEN f.payload->>'direction'='above' THEN p.modal_price>=(f.payload->>'threshold')::numeric ELSE p.modal_price<=(f.payload->>'threshold')::numeric END,'delivery','in_app_only')) FROM prices p WHERE f.owner_id=p.owner_id AND f.kind=p.kind AND f.id=p.id; GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed; END; $$;
REVOKE ALL ON FUNCTION public.evaluate_farmer_alerts() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.evaluate_farmer_alerts() TO service_role;
COMMENT ON FUNCTION public.evaluate_farmer_alerts() IS 'Called after scheduled official retrieval; account-private in-app results only, no email/SMS/push claim.';